import React from "react";
import { HashRouter, Routes, Route } from "react-router-dom"
import ApplicationLogin from "./applicationLogin";
import Admin from "./admin/admin";
import "./App.css";
const LazyNavigation = React.lazy( () => import("./navigationpage"))
const LazyMainHome = React.lazy( () => import("./defaultresort/mainhome/mainhome") )
const LazyAllRooms = React.lazy( () => import("./roomslist/allrooms"))
const LazyForm = React.lazy( () => import("./roomslist/forms"))
const LazyLogin = React.l


function App() {
  return (
    <HashRouter>
      <LazyNavigation />
          <Routes>
            <Route path="/" element={
              <React.Suspense fallback={<></>}>
                <LazyMainHome />
              </React.Suspense>
            } />

            <Route path="/resortlist" element={
              <React.Suspense fallback={<></>}>
                <LazyAllRooms />
              </React.Suspense>
             } />

             <Route path="/Forms" element={
              <React.Suspense fallback={<></>} >
                <LazyForm />
              </React.Suspense>
             } />

             <Route path="/login" element={<ApplicationLogin />} />
             <Route path="/admin" element={<Admin />} />

          </Routes>
    </HashRouter>
  );
}

export default App;
